# ABOUTME: Base home-manager configuration shared across all platforms
# ABOUTME: Provides common module imports, packages, and webframp module defaults
{
  config,
  lib,
  pkgs,
  inputs,
  outputs,
  ...
}: {
  imports =
    [
      ./programs.nix
      inputs.shelley-herdr.homeManagerModules.default
    ]
    ++ (with outputs.homeManagerModules; [
      zsh
      bat
      claudeCode
      delta
      direnv
      doom
      fzf
      git
      herdr
      kiroCli
      mail
      pi
      tmux
      twitchWatcher
    ]);

  nix = {
    package = lib.mkDefault pkgs.nix;
    settings = {
      experimental-features = ["nix-command" "flakes"];
      warn-dirty = false;
    };
  };

  # Note: nixpkgs.config is set per-host for standalone home-manager configs.
  # NixOS hosts using useGlobalPkgs inherit nixpkgs config from NixOS.
  programs.home-manager.enable = true;

  # Home defaults with platform-appropriate paths
  home = {
    username = lib.mkDefault "sme";
    homeDirectory = lib.mkDefault (
      if pkgs.stdenv.hostPlatform.isDarwin
      then "/Users/${config.home.username}"
      else "/home/${config.home.username}"
    );
    stateVersion = lib.mkDefault "24.05";
    # Common packages for all platforms (hosts can add more via home.packages)
    packages = import ./packages.nix {inherit lib pkgs;};
  };

  home.file.".local/bin/tmux-jump-bell" = {
    source = ../shared/includes/tmux-jump-bell.sh;
    executable = true;
  };

  # Shared webframp module configuration
  # Hosts can override specific options as needed
  webframp.bat.enable = true;
  webframp.claudeCode.enable = true;
  webframp.doom.enable = true;
  webframp.herdr.enable = true;
  programs.shelley-herdr.enable = true;
  webframp.kiroCli.enable = true;
  webframp.pi.enable = true;
  webframp.delta.enable = true;
  webframp.direnv = {
    enable = true;
    whitelist = ["~/src/o11n"];
  };
  webframp.fzf.enable = true;
  webframp.git = {
    enable = true;
    extraIncludes = [{path = "~/.config/git/forge.conf";}];
  };
  webframp.tmux.enable = true;
  webframp.zsh.enable = true;

  # Linux-specific defaults (can be overridden by hosts)
  webframp.tmux.terminal = lib.mkIf pkgs.stdenv.hostPlatform.isLinux "tmux-256color";
  webframp.zsh.enableVterm = lib.mkIf pkgs.stdenv.hostPlatform.isLinux (lib.mkDefault false);

  # Prune stale zcompdump files weekly (they accumulate per-PID on NixOS rebuilds)
  systemd.user.services.zcompdump-cleanup = lib.mkIf pkgs.stdenv.hostPlatform.isLinux {
    Unit.Description = "Remove stale zcompdump files older than 7 days";
    Service = {
      Type = "oneshot";
      ExecStart = "${pkgs.findutils}/bin/find ${config.home.homeDirectory} -maxdepth 1 -name '.zcompdump.*' -mtime +7 -delete";
    };
  };
  systemd.user.timers.zcompdump-cleanup = lib.mkIf pkgs.stdenv.hostPlatform.isLinux {
    Unit.Description = "Weekly zcompdump cleanup";
    Timer = {
      OnCalendar = "weekly";
      Persistent = true;
    };
    Install.WantedBy = ["timers.target"];
  };
}
---
diff --git c/home/sme/shared/base.nix i/home/sme/shared/base.nix
index c55fdc3..0b5e3ef 100644
--- c/home/sme/shared/base.nix
+++ i/home/sme/shared/base.nix
@@ -11,7 +11,7 @@
   imports =
     [
       ./programs.nix
-      inputs.shelly-herdr.homeManagerModules.default
+      inputs.shelley-herdr.homeManagerModules.default
     ]
     ++ (with outputs.homeManagerModules; [
       zsh
@@ -66,7 +66,7 @@
   webframp.claudeCode.enable = true;
   webframp.doom.enable = true;
   webframp.herdr.enable = true;
-  programs.shelly-herdr.enable = true;
+  programs.shelley-herdr.enable = true;
   webframp.kiroCli.enable = true;
   webframp.pi.enable = true;
   webframp.delta.enable = true;
---
