p='modules/home-manager/default.nix'
s=open(p).read()
s=s.replace("{
  bat = import ./bat.nix;","{
  agentSkills = import ./agent-skills.nix;
  bat = import ./bat.nix;")
open(p,'w').write(s)
p='home/sme/shared/base.nix'
s=open(p).read()
s=s.replace("      zsh
      bat
","      zsh
      agentSkills
      bat
",1)
s=s.replace("  webframp.bat.enable = true;
","  webframp.agentSkills = {
    enable = true;
    skills = ["writing-editorial"];
  };
  webframp.bat.enable = true;
",1)
open(p,'w').write(s)
EOF
git diff modules/home-manager/default.nix home/sme/shared/base.nix
git add config/skills modules/home-manager/agent-skills.nix modules/home-manager/default.nix home/sme/shared/base.nix
make fmt 2>&1 | tail -3; git diff --stat

